-- Spam and profanity filter (Hebrew + English). Run AFTER schema.sql, in the Supabase SQL editor.
-- Safe to run again. Generated by scripts/build-moderation-sql.mjs from src/lib/moderation.js: edit there.
--
-- Blocks, on insert and on edit: offensive words (also with niqqud, final letters, l33t, s p a c e s,
-- repeated letters or a Hebrew prefix like "ו"/"ה"), links and email addresses, phone numbers in public
-- text, and floods of one repeated character. Also blocks sending the same group message or inquiry twice.
-- Admins are not checked. To block another word without a deploy:
--   insert into public.moderation_words values ('המילה', 'word');   -- 'word' = whole word, 'part' = anywhere

create table if not exists public.moderation_words (
  word text primary key,
  kind text not null check (kind in ('word', 'part', 'allow'))
);
alter table public.moderation_words enable row level security;  -- no policies: only the dashboard edits it

create or replace function public.mod_normalize(t text) returns text
language sql immutable set search_path = '' as $$
  select regexp_replace(
    translate(
      regexp_replace(lower(coalesce(t, '')), '[\u0591-\u05C7\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF\u00AD]', '', 'g'),
      'ךםןףץ013457@$', 'כמנפצoieastas'),
    '(.)\1+', '\1', 'g')
$$;

-- Words of the text, with runs of single letters joined ("f u c k" -> "fuck").
create or replace function public.mod_tokens(t text) returns text[]
language plpgsql immutable set search_path = '' as $$
declare tok text; run text := ''; result text[] := '{}';
begin
  foreach tok in array regexp_split_to_array(public.mod_normalize(t), '[^a-zא-ת]+') loop
    continue when tok = '';
    if length(tok) = 1 then run := run || tok; continue; end if;
    if run <> '' then result := result || run; run := ''; end if;
    result := result || tok;
  end loop;
  if run <> '' then result := result || run; end if;
  return result;
end $$;

-- Why the text is blocked ('profanity', 'link', 'phone', 'flood') or null when it is fine.
create or replace function public.mod_check(t text, allow_phone boolean default false) returns text
language plpgsql stable security definer set search_path = '' as $$
declare
  toks text[]; tok text; cand text; pair text; i int; j int;
  words text[]; parts text[]; allowed text[];
begin
  if t is null or t = '' then return null; end if;
  select coalesce(array_agg(public.mod_normalize(word)) filter (where kind = 'word'), '{}'),
         coalesce(array_agg(public.mod_normalize(word)) filter (where kind = 'part'), '{}'),
         coalesce(array_agg(public.mod_normalize(word)) filter (where kind = 'allow'), '{}')
    into words, parts, allowed from public.moderation_words;
  toks := public.mod_tokens(t);
  for i in 1 .. coalesce(array_length(toks, 1), 0) loop
    tok := toks[i];
    if not tok = any(allowed) then
      if tok = any(words) then return 'profanity'; end if;
      j := 1;  -- also without up to 3 Hebrew prefix letters (ו ש ה ב ל מ כ)
      while j <= 3 and j < length(tok) - 1 and position(substr(tok, j, 1) in 'ושהבלמכ') > 0 loop
        cand := substr(tok, j + 1);
        if cand = any(words) then return 'profanity'; end if;
        j := j + 1;
      end loop;
    end if;
    pair := tok || coalesce(toks[i + 1], '');
    if exists (select 1 from unnest(parts) p where position(p in pair) > 0) then return 'profanity'; end if;
  end loop;
  if regexp_replace(t, '[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF\u00AD]', '', 'g')
     ~* '(https?://|www\.|\yt\.me/|\ywa\.me/|\ybit\.ly\y|[a-z0-9-]+\.(com|net|org|info|biz|io|co|il|ru|xyz|me|ly|link|site|online|app|shop|top|click)\y|[^\s@]+@[^\s@]+\.[a-z]{2,})'
    then return 'link'; end if;
  if not allow_phone and regexp_replace(t, '[\s\-.()]', '', 'g') ~ '(\+?972|0)5[0-9]{8}|(\+?972|0)[2-9][0-9]{7}'
    then return 'phone'; end if;
  if t ~ '(.)\1{9,}' then return 'flood'; end if;
  return null;
end $$;

-- Trigger: arguments are the columns to check; "column:private" allows a phone number in it.
create or replace function public.moderate_content() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  arg text; col text; val text; why text;
  n jsonb := to_jsonb(new);
  o jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
begin
  if public.is_admin() or coalesce(auth.jwt() ->> 'role', '') = 'service_role'
     or (auth.uid() is null and session_user <> 'authenticator') then  -- dashboard / SQL editor
    return new;
  end if;
  foreach arg in array tg_argv loop
    col := split_part(arg, ':', 1);
    val := n ->> col;
    continue when val is null or val is not distinct from (o ->> col);
    why := public.mod_check(val, split_part(arg, ':', 2) = 'private');
    if why is not null then
      raise exception 'moderation: %', why using errcode = '23514', detail = col;
    end if;
  end loop;
  if tg_op = 'INSERT' and tg_table_name in ('group_messages', 'inquiries') then
    if tg_table_name = 'group_messages' then
      perform 1 from public.group_messages m where m.user_id = (n ->> 'user_id')::uuid and m.group_id = (n ->> 'group_id')::uuid
        and m.text = n ->> 'text' and m.created_at > now() - interval '10 minutes';
    else
      perform 1 from public.inquiries q where q.user_id = (n ->> 'user_id')::uuid and q.tutor_id = (n ->> 'tutor_id')::uuid
        and q.message = n ->> 'message' and q.created_at > now() - interval '1 hour';
    end if;
    if found then raise exception 'moderation: duplicate' using errcode = '23514'; end if;
  end if;
  return new;
end $$;

drop trigger if exists moderate on public.reviews;
create trigger moderate before insert or update on public.reviews
  for each row execute function public.moderate_content('text', 'user_name:private');
drop trigger if exists moderate on public.inquiries;
create trigger moderate before insert or update on public.inquiries
  for each row execute function public.moderate_content('name:private', 'message:private', 'reply:private');
drop trigger if exists moderate on public.group_messages;
create trigger moderate before insert or update on public.group_messages
  for each row execute function public.moderate_content('text', 'user_name:private');
drop trigger if exists moderate on public.tutors;
create trigger moderate before insert or update on public.tutors
  for each row execute function public.moderate_content('name:private', 'headline', 'about', 'education', 'city:private', 'area:private');
drop trigger if exists moderate on public.groups;
create trigger moderate before insert or update on public.groups
  for each row execute function public.moderate_content('title', 'description', 'location:private', 'time:private');
drop trigger if exists moderate on public.group_seats;
create trigger moderate before insert or update on public.group_seats
  for each row execute function public.moderate_content('name:private', 'note:private');

-- Trigger and helper functions are not API endpoints.
revoke execute on function public.moderate_content(), public.mod_check(text, boolean) from anon, authenticated, public;

